package io.github.diodeme.ji.remote;

import java.nio.file.Path;
import java.util.Optional;

/** Explicit SSH target; an absent key delegates authentication to the system SSH agent. */
public record SshTarget(String user, String host, int port, Optional<Path> identityFile) {
    public SshTarget {
        if (user == null || user.isBlank() || host == null || host.isBlank()
                || port < 1 || port > 65_535) {
            throw new IllegalArgumentException("invalid SSH target");
        }
        identityFile = identityFile == null ? Optional.empty() : identityFile;
    }

    public String destination() { return user + "@" + host; }
}
